def populate_branch_dedicated_warehouses(apps, schema_editor):
    Branch = apps.get_model("tenancy", "Branch")
    Warehouse = apps.get_model("tenancy", "Warehouse")
    BranchWarehouse = apps.get_model("tenancy", "BranchWarehouse")
    BranchWarehouseAssignment = apps.get_model("tenancy", "BranchWarehouseAssignment")
    WarehouseTransferPermission = apps.get_model("tenancy", "WarehouseTransferPermission")

    assigned_wh_ids = set()

    for branch in Branch.objects.all():
        if BranchWarehouseAssignment.objects.filter(branch=branch).exists():
            continue

        default_bw = BranchWarehouse.objects.filter(
            branch=branch,
            is_default=True,
        ).exclude(warehouse_id__in=assigned_wh_ids).first()

        wh = default_bw.warehouse if default_bw else None

        if not wh:
            wh = Warehouse.objects.filter(
                branch=branch,
            ).exclude(id__in=assigned_wh_ids).first()

        if not wh:
            any_bw = BranchWarehouse.objects.filter(
                branch=branch,
            ).exclude(warehouse_id__in=assigned_wh_ids).first()
            if any_bw:
                wh = any_bw.warehouse

        if not wh:
            wh_code = f"{branch.code or 'BR'}-WH"
            wh = Warehouse.objects.create(
                organization=branch.organization,
                name=f"{branch.name} Warehouse",
                code=wh_code[:32],
                warehouse_type="branch",
                branch=branch,
                is_active=branch.is_active,
            )

        wh.warehouse_type = "branch"
        wh.save(update_fields=["warehouse_type"])
        assigned_wh_ids.add(wh.id)

        BranchWarehouseAssignment.objects.create(
            organization=branch.organization,
            branch=branch,
            warehouse=wh,
            is_active=branch.is_active,
            notes="Migrated from existing branch configuration",
        )

    for bw in BranchWarehouse.objects.filter(can_replenish=True).select_related("branch", "warehouse"):
        assignment = BranchWarehouseAssignment.objects.filter(branch=bw.branch).first()
        if assignment and assignment.warehouse_id != bw.warehouse_id:
            WarehouseTransferPermission.objects.get_or_create(
                organization=bw.organization,
                source_warehouse=bw.warehouse,
                destination_warehouse=assignment.warehouse,
                defaults={
                    "can_request": bw.can_replenish,
                    "can_dispatch": True,
                    "priority": bw.priority,
                    "is_active": True,
                    "notes": "Migrated from branch fulfillment mapping",
                },
            )


